"""Finding the stretches of opening hours that nobody is covering."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import ProjectError

class OutsideHoursError(ProjectError):
    """A worked span sticks out past opening hours."""

def check_within(worked: Iterable[Span], hours: Span) -> None:
    for span in worked:
        if span.start < hours.start or span.end > hours.end:
            raise OutsideHoursError(
                f"{format_span(span)} is outside opening hours {format_span(hours)}"
            )

def uncovered(worked: Iterable[Span], hours: Span) -> List[Span]:
    points = [hours.start, hours.end]
    for span in merge_spans(worked):
        points[-1:-1] = [span.start, span.end]
    pairs = zip(points[0::2], points[1::2])
    return [Span(begin, stop) for begin, stop in pairs if begin < stop]

def gap_label(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"

def find_gaps(worked: Iterable[Span], hours: Span) -> List[str]:
    """One label per uncovered stretch, such as 'gap 12:00-13:00 (60 min)'."""
    spans = list(worked)
    check_within(spans, hours)
    return [gap_label(gap) for gap in uncovered(spans, hours)]

