# owner: platform
import unittest
from hourglass.parsing import parse_span
from hourglass.gaps import OutsideHoursError, find_gaps

OPEN = parse_span("09:00-17:00")

class FindGapsTests(unittest.TestCase):
    def spans(self, *texts):
        return [parse_span(text) for text in texts]

    def test_gap_in_the_middle(self):
        worked = self.spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_no_workers_means_one_big_gap(self):
        self.assertEqual(find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_coverage_has_no_gaps(self):
        worked = self.spans("09:00-13:00", "12:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_gaps_at_both_ends_and_unsorted_input(self):
        worked = self.spans("14:00-15:00", "10:00-12:00", "11:00-13:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 13:00-14:00 (60 min)",
                "gap 15:00-17:00 (120 min)"
            ]
        )

    def test_touching_spans_leave_no_gap(self):
        worked = self.spans("09:00-12:00", "12:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_span_outside_hours_raises(self):
        for text in ("08:00-10:00", "16:00-18:00"):
            with self.assertRaises(OutsideHoursError):
                find_gaps(self.spans(text), OPEN)

    def test_works_with_a_generator(self):
        worked = (span for span in self.spans("09:00-16:00"))
        self.assertEqual(find_gaps(worked, OPEN), ["gap 16:00-17:00 (60 min)"])
